import assert from 'node:assert/strict';
import { openBrowser } from '../dist/browser.js';
import { CDP } from '../dist/cdp.js';
import { Page } from '../dist/page.js';
const fixture = 'data:text/html,' + encodeURIComponent('<meta name="viewport" content="width=device-width, initial-scale=1"><title>Viewport fixture</title><style>body{margin:0}.mode:after{content:"desktop"}@media(max-width:430px){.mode:after{content:"mobile"}}</style><div class="mode"></div>');
const results = [];
for (const headless of [true,false]) {
 const browser = await openBrowser({headless});
 let cdp;
 try {
  cdp = await CDP.connect(browser.endpoint);
  const version = await cdp.send('Browser.getVersion');
  const { targetId } = await cdp.send('Target.createTarget',{url:'about:blank'});
  const page = await Page.attach(cdp,targetId);
  const observer = await Page.attach(cdp,targetId);
  const read = () => page.evaluate(()=>({width:innerWidth,height:innerHeight,dpr:devicePixelRatio,visualWidth:visualViewport.width,documentWidth:document.documentElement.clientWidth,mobileMedia:matchMedia('(max-width:430px)').matches}));
  await page.goto(fixture);
  const before = await read();
  for(const mobile of [true,false]) {
   const sent=[];
   cdp.observeCommand=(method,params,sessionId)=>{if(method.startsWith('Emulation.'))sent.push({method,params,sessionId});};
   await page.cdp('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile});
   const immediate = await read();
   await page.goto(fixture+'#next');
   await observer.screenshot();
   const afterObservation = await read();
   assert.equal(immediate.width,390);
   assert.equal(afterObservation.width,390);
   assert.equal(afterObservation.height,844);
   assert.equal(afterObservation.dpr,1);
   assert.equal(afterObservation.mobileMedia,true);
   assert.equal(sent[0].sessionId,page.sessionId);
   results.push({headless,mobile,browser:version.product,before,immediate,afterObservation,pageSessionRouted:true});
   await page.cdp('Emulation.clearDeviceMetricsOverride');
  }
 } finally {cdp?.close();await browser.close();}
}
console.log(JSON.stringify({probe:'SDK page-scoped viewport emulation in isolated stock Chrome; no provider or remote browser',results,passed:results.length,cleanup:'All probe-owned Chrome processes closed by awaited finally'},null,2));
